// One-off operator check for #2072: a fresh browser context signs in with a
// soak wallet key (read from stdin) and reaches the vault. Prints no key.
import { chromium } from '@playwright/test';
import { text } from 'node:stream/consumers';
import type { Hex } from 'viem';
import { FilesPage } from '../page-objects/files.page';
import { LoginPage } from '../page-objects/login.page';
import { installTestWallet, TEST_WALLET_NAME } from '../staging/wallet';

const role = process.argv[2] ?? 'account';
const base = 'https://app-staging.cipherbox.cc';

async function main(): Promise<void> {
  const raw = (await text(process.stdin)).trim();
  const key = (raw.startsWith('0x') ? raw : `0x${raw}`) as Hex;
  if (!/^0x[0-9a-fA-F]{64}$/.test(key)) throw new Error('stdin is not a 32-byte hex key');

  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext();
  const page = await context.newPage();
  try {
    await installTestWallet(page, key);
    await page.goto(base);
    const login = new LoginPage(page);
    const files = new FilesPage(page);
    await login.walletButton.waitFor({ state: 'visible', timeout: 60_000 });
    const started = Date.now();
    await login.walletButton.click();
    await page
      .getByRole('button', { name: `Connect with ${TEST_WALLET_NAME}`, exact: true })
      .click();
    const refused = await login.refusal(files.browser, 300_000);
    if (refused !== null) throw new Error(`the login was refused: ${refused}`);
    await page.waitForTimeout(5_000);
    const rows = await files.browser.locator('.file-list-item').count();
    const empty = await files.emptyState.isVisible();
    console.log(
      `${role}: reached the vault in ${Math.round((Date.now() - started) / 1000)} s; ` +
        `root rows=${rows}; empty state=${empty}; url path=${new URL(page.url()).pathname}`
    );
  } catch (failure) {
    const shot = `test-results/soak-account-check-${role}.png`;
    await page.screenshot({ path: shot }).catch(() => undefined);
    console.log(`${role}: FAILED: ${(failure as Error).message.split('\n')[0]} (screenshot ${shot})`);
    process.exitCode = 1;
  } finally {
    await browser.close();
  }
}

void main();

